import React from "react";
import { useNavigate } from "react-router-dom";

import { useAuth } from "../context/AuthContext.js";

import "./Dashboard.css";

function Dashboard() {
  const {
    user,
    logout,
  } = useAuth();

  const navigate = useNavigate();

  const handleLogout = () => {
    logout();

    navigate("/", {
      replace: true,
    });
  };

  return (
    <div className="dashboard-page">
      <header className="dashboard-header">
        <div className="dashboard-container dashboard-header-content">
          <div>
            <h1 className="dashboard-brand">
              Tenant<span>Cart</span>
            </h1>

            <p className="dashboard-subtitle">
              Merchant dashboard
            </p>
          </div>

          <div className="dashboard-actions">
            <span className="dashboard-user">
              {user?.name || "Merchant"}
            </span>

            <button
              type="button"
              onClick={handleLogout}
              className="dashboard-logout"
            >
              Logout
            </button>
          </div>
        </div>
      </header>

      <main className="dashboard-container dashboard-main">
        <section className="dashboard-welcome">
          <p className="dashboard-eyebrow">
            Welcome back
          </p>

          <h2 className="dashboard-heading">
            Hello, {user?.name || "Merchant"}.
          </h2>

          <p className="dashboard-description">
            Manage your products, track your orders, and understand your store
            performance from one workspace.
          </p>
        </section>

        <section className="dashboard-cards">
          <DashboardCard
            title="Products"
            description="Add and manage your store products."
          />

          <DashboardCard
            title="Orders"
            description="Review and update customer orders."
          />

          <DashboardCard
            title="Analytics"
            description="Explore your store performance."
          />
        </section>
      </main>
    </div>
  );
}

function DashboardCard({
  title,
  description,
}) {
  return (
    <article className="dashboard-card">
      <h3>
        {title}
      </h3>

      <p>
        {description}
      </p>

      <button
        type="button"
        className="dashboard-card-button"
      >
        Open {title.toLowerCase()} →
      </button>
    </article>
  );
}

export default Dashboard;
